package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRecs []OrderRec
var orderIdx int
var orderRec OrderRec

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatIntPadded(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	} else if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func formatEdited(v decimal.Decimal, pic string) string {
	// find dot
	dotPos := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = pic[:dotPos]
		fracPic = pic[dotPos+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}
	scale := fracSlots

	absVal := v.Abs()
	// Ensure quantized to scale (truncate/round already done by caller)
	// Build integer and fractional strings via string fixed
	// Use Shift to avoid float
	var intPartStr string
	var fracPartStr string
	if scale > 0 {
		s := absVal.StringFixed(int32(scale))
		// StringFixed may produce "-xxx", but abs so no minus
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", scale)
		}
		// pad frac to scale
		if len(fracPartStr) < scale {
			fracPartStr = fracPartStr + strings.Repeat("0", scale-len(fracPartStr))
		} else if len(fracPartStr) > scale {
			fracPartStr = fracPartStr[:scale]
		}
	} else {
		intPartStr = absVal.StringFixed(0)
		// remove possible decimal point
		if idx := strings.Index(intPartStr, "."); idx >= 0 {
			intPartStr = intPartStr[:idx]
		}
		fracPartStr = ""
	}
	// handle high-order truncation
	if len(intPartStr) > intSlots {
		intPartStr = intPartStr[len(intPartStr)-intSlots:]
	}
	// left pad integer to intSlots with zeros
	if len(intPartStr) < intSlots {
		intPartStr = strings.Repeat("0", intSlots-len(intPartStr)) + intPartStr
	}

	// Build output buffer initialized with picture chars
	out := []rune(pic)

	// Fill integer digit slots
	idxDigit := 0
	for i, c := range intPic {
		if c == 'Z' || c == '9' {
			out[i] = rune(intPartStr[idxDigit])
			idxDigit++
		} else {
			// comma stays for now, will be handled in suppression
			out[i] = c
		}
	}
	// Fill fraction digit slots
	if dotPos >= 0 {
		// dot stays
		out[dotPos] = '.'
		idxDigit = 0
		for i, c := range fracPic {
			pi := dotPos + 1 + i
			if c == 'Z' || c == '9' {
				var ch byte
				if idxDigit < len(fracPartStr) {
					ch = fracPartStr[idxDigit]
				} else {
					ch = '0'
				}
				out[pi] = rune(ch)
				idxDigit++
			} else {
				out[pi] = c
			}
		}
	}

	// Apply Z suppression on integer part
	encounteredNonZero := false
	for i := 0; i < len(intPic); i++ {
		pch := intPic[i]
		if pch == 'Z' || pch == '9' {
			if !encounteredNonZero {
				if out[i] == '0' && pch == 'Z' {
					out[i] = ' '
				} else {
					// keep digit
					if out[i] != '0' {
						encounteredNonZero = true
					} else {
						// zero on a '9' -> keep but no longer suppressing
						encounteredNonZero = true
					}
				}
			}
		} else if pch == ',' {
			if !encounteredNonZero {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		} else {
			// any other literal
			out[i] = rune(pch)
		}
	}
	// fraction part literals remain as is (already)
	return string(out)
}

func loadOrderFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// no file -> treat as empty
		orderRecs = []OrderRec{}
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// increase buffer for long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// Scanner strips \n and \r; keep other spaces
		// Pad to 15
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		rec := OrderRec{}
		rec.OrId = line[0:5]
		rec.OrStat = line[5:6]
		qtyStr := line[6:9]
		qtyStrTrim := strings.TrimSpace(qtyStr)
		var q int64
		if qtyStrTrim == "" {
			q = 0
		} else {
			// parse as integer, ignoring non-digit? assume digits
			var v int64
			for _, ch := range qtyStr {
				if ch >= '0' && ch <= '9' {
					v = v*10 + int64(ch-'0')
				}
			}
			// But if string has spaces, above will skip; we counted digits only.
			// For fully numeric, v is correct.
			// To keep truncation semantics for 3 digits, high-order drop is inherent in parsing 3-char field? But numeric field drop is low-order keep; however parsing as integer of 3 digits already limited.
			q = v
			// Ensure we keep only low-order digits that fit if longer? Not needed.
		}
		rec.OrQty = q
		priceStr := line[9:15]
		// digits only with implied decimal V99
		var pInt int64
		for _, ch := range priceStr {
			if ch >= '0' && ch <= '9' {
				pInt = pInt*10 + int64(ch-'0')
			} else if ch == ' ' {
				// treat space as 0? For padded, count as 0
				pInt = pInt * 10
			}
		}
		rec.OrPrice = decimal.New(pInt, -2)
		orderRecs = append(orderRecs, rec)
	}
}

func READPARA() {
	if orderIdx >= len(orderRecs) {
		WsEofFlag = "Y"
		return
	}
	orderRec = orderRecs[orderIdx]
	orderIdx++
}

func SHOWPARA() {
	WsQtyEd = formatEdited(decimal.NewFromInt(orderRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func PROCESSPARA() {
	WsTotal = decimal.NewFromInt(0)
	if orderRec.OrQty == 0 {
		WsBadQty++
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		WsTotal = decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice)
		// Truncate to 2 decimals (target scale) – product already scale 2, so truncate
		WsTotal = WsTotal.Truncate(2)
		// Store truncation to picture 9(8)V99 – keep low-order digits if overflow; for decimal we can ignore as values small
		WsNewCount++
		SHOWPARA()
	} else if orderRec.OrStat == "S" {
		one05 := decimal.New(105, -2) // 1.05
		raw := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice).Mul(one05)
		WsTotal = raw.Round(2)
		WsShipCount++
		SHOWPARA()
	} else if orderRec.OrStat == "C" {
		WsCancelCount++
		SHOWPARA()
	} else {
		WsInvalid++
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	READPARA()
}

func SUMMARYPARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatIntPadded(WsNewCount, 2), formatIntPadded(WsShipCount, 2), formatIntPadded(WsCancelCount, 2))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatIntPadded(WsInvalid, 2), formatIntPadded(WsBadQty, 2))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	loadOrderFile()
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	SUMMARYPARA()
}
